/**
 * Verifies the icon set.
 *
 * Icons are generated by `npm run icons`, which drives a headless browser: it
 * sets the viewport to the icon size and screenshots it. That made a subtle
 * failure possible — measuring glyph metrics mid-render reset the viewport, so
 * the first icon of each mark was written at 1200x400 while still being named
 * `favicon-16x16.png`. Nothing about the file name is evidence of its size.
 *
 * This reads the bytes directly: no browser, no build, so it can run anywhere.
 *
 *   node tools/check-icons.mjs
 */

import { readFileSync, existsSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { join } from 'node:path';

const imageDir = fileURLToPath(new URL('../public/images', import.meta.url));

const EXPECTED_PNG = [
  { file: 'favicon-16x16.png', width: 16, height: 16 },
  { file: 'favicon-32x32.png', width: 32, height: 32 },
  { file: 'apple-touch-icon.png', width: 180, height: 180 },
  { file: 'android-chrome-192x192.png', width: 192, height: 192 },
  { file: 'android-chrome-512x512.png', width: 512, height: 512 },
];

const PNG_SIGNATURE = '89504e470d0a1a0a';
const ICO_ENTRY_SIZE = 16;
const ICO_HEADER_SIZE = 6;

const problems = [];

for (const { file, width, height } of EXPECTED_PNG) {
  const path = join(imageDir, file);
  if (!existsSync(path)) {
    problems.push(`${file}: missing`);
    continue;
  }
  const buffer = readFileSync(path);
  if (buffer.subarray(0, 8).toString('hex') !== PNG_SIGNATURE) {
    problems.push(`${file}: not a PNG`);
    continue;
  }
  const actualWidth = buffer.readUInt32BE(16);
  const actualHeight = buffer.readUInt32BE(20);
  if (actualWidth !== width || actualHeight !== height) {
    problems.push(`${file}: is ${actualWidth}x${actualHeight}, expected ${width}x${height}`);
  }
}

// The .ico must be structurally valid or browsers silently ignore it.
const icoPath = join(imageDir, 'favicon.ico');
if (!existsSync(icoPath)) {
  problems.push('favicon.ico: missing');
} else {
  const ico = readFileSync(icoPath);
  const reserved = ico.readUInt16LE(0);
  const type = ico.readUInt16LE(2);
  const count = ico.readUInt16LE(4);

  if (reserved !== 0) problems.push(`favicon.ico: reserved field is ${reserved}, expected 0`);
  if (type !== 1) problems.push(`favicon.ico: type is ${type}, expected 1 (icon)`);
  if (count < 1) problems.push('favicon.ico: contains no images');

  for (let i = 0; i < count; i++) {
    const at = ICO_HEADER_SIZE + i * ICO_ENTRY_SIZE;
    if (at + ICO_ENTRY_SIZE > ico.length) {
      problems.push(`favicon.ico: directory entry ${i} runs past the end of the file`);
      break;
    }
    const width = ico.readUInt8(at) || 256;
    const height = ico.readUInt8(at + 1) || 256;
    const bytes = ico.readUInt32LE(at + 8);
    const offset = ico.readUInt32LE(at + 12);

    if (offset + bytes > ico.length) {
      problems.push(`favicon.ico: entry ${width}x${height} points past the end of the file`);
      continue;
    }
    const payload = ico.subarray(offset, offset + 8).toString('hex');
    if (payload !== PNG_SIGNATURE) {
      problems.push(`favicon.ico: entry ${width}x${height} is not a PNG payload`);
      continue;
    }
    const actualWidth = ico.readUInt32BE(offset + 16);
    const actualHeight = ico.readUInt32BE(offset + 20);
    if (actualWidth !== width || actualHeight !== height) {
      problems.push(
        `favicon.ico: entry declares ${width}x${height} but contains ${actualWidth}x${actualHeight}`,
      );
    }
  }
}

if (problems.length === 0) {
  console.log(`icons: ${EXPECTED_PNG.length} PNGs and favicon.ico are valid at their declared sizes`);
  process.exit(0);
}

console.error(`icons: ${problems.length} problem(s)`);
for (const problem of problems) console.error(`  - ${problem}`);
process.exit(1);
